rm","originality"],"concern":"Source attribution and ethical use of artist vocabulary require teacher guidance."},{"level":3,"num":6,"title":"The Three Minor Scales","objective":"Differentiate natural, harmonic, and melodic minor and apply each appropriately.","lessons":[{"title":"Compare Minor Forms","objective":"Explain interval differences among the forms."},{"title":"Technique and Fingering","objective":"Play selected forms evenly with safe fingering."},{"title":"Minor-Scale Musical Uses","objective":"Use a minor form in a phrase or improvisation."}],"practiceTitle":"Minor-Form Rotation","practiceInstructions":"Practice the three forms in a teacher-selected key and compare their sound.","challengeTitle":"Three Minor Scales Challenge","evidence":"Audio/video of all three forms in approved keys plus a musical application.","rubric":[{"name":"Scale accuracy","weight":30},{"name":"Fingering and evenness","weight":25},{"name":"Aural distinction","weight":20},{"name":"Musical application","weight":15},{"name":"Reflection and completeness","weight":10}],"aria":["raised scale degrees","fingering","aural comparison","application"],"concern":"Number of keys, octaves, and melodic-minor convention require teacher approval."},{"level":3,"num":7,"title":"Improvising with Modes","objective":"Improvise with selected modes while sustaining the intended tonal center and character.","lessons":[{"title":"Target Characteristic Tones","objective":"Emphasize defining modal tones."},{"title":"Match Mode to Harmony","objective":"Select an appropriate mode for a vamp."},{"title":"Shape a Modal Improvisation","objective":"Develop coherent modal phrases."}],"practiceTitle":"Modal Vamp Exploration","practiceInstructions":"Improvise short phrases over Dorian, Mixolydian, or teacher-approved vamps.","challengeTitle":"Modal Improvisation Challenge","evidence":"Audio/video modal improvisation over an approved vamp with rationale.","rubric":[{"name":"Modal note accuracy","weight":25},{"name":"Tonal-center control","weight":25},{"name":"Phrasing and rhythm","weight":20},{"name":"Creativity and expression","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["characteristic tones","tonal center","harmonic fit","phrase development"],"concern":"Backing tracks and exact modal requirements need teacher approval."},{"level":3,"num":8,"title":"Introduction to Jazz Piano","objective":"Apply foundational jazz harmony, rhythm, and improvisational interaction.","lessons":[{"title":"Jazz Form and Listening","objective":"Identify basic jazz form and ensemble roles."},{"title":"Core Progressions and Voicings","objective":"Play a selected jazz progression."},{"title":"First Jazz Conversation","objective":"Create responsive phrases with space and swing."}],"practiceTitle":"Jazz Conversation Practice","practiceInstructions":"Alternate comping and short improvised responses over a simple form.","challengeTitle":"Intro Jazz Piano Challenge","evidence":"Audio/video jazz performance demonstrating chords, rhythm, and a short improvisation.","rubric":[{"name":"Harmony and form","weight":25},{"name":"Jazz rhythm and feel","weight":25},{"name":"Improvisation","weight":20},{"name":"Interaction and expression","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["listening","ii-V-I","swing","call and response","stylistic respect"],"concern":"Repertoire, swing interpretation, and historical context require teacher curation."},{"level":3,"num":9,"title":"Rhythmic Independence","objective":"Maintain contrasting rhythmic roles between hands with control and musical flow.","lessons":[{"title":"Independent Subdivisions","objective":"Perform each rhythmic layer separately."},{"title":"Layer Contrasting Patterns","objective":"Combine contrasting patterns gradually."},{"title":"Apply Independence Musically","objective":"Use independence in a short musical texture."}],"practiceTitle":"Layered Rhythm Ladder","practiceInstructions":"Add one rhythmic layer at a time at a safe tempo.","challengeTitle":"Rhythmic Independence Challenge","evidence":"Video/audio of contrasting hand rhythms in an exercise and musical excerpt.","rubric":[{"name":"Rhythmic accuracy","weight":30},{"name":"Hand independence","weight":25},{"name":"Pulse stability","weight":20},{"name":"Technique and control","weight":15},{"name":"Reflection and completeness","weight":10}],"aria":["subdivision","layered practice","polyrhythm preparation","tension monitoring"],"concern":"Exact rhythmic ratios and difficulty progression are not standardized in source."},{"level":3,"num":10,"title":"Arranging a Pop Song","objective":"Transform a pop song into a coherent piano arrangement with personal musical choices.","lessons":[{"title":"Analyze Song Structure","objective":"Map form, melody, harmony, and key moments."},{"title":"Design Piano Texture","objective":"Choose accompaniment and register by section."},{"title":"Refine the Full Arrangement","objective":"Create transitions and a complete performance plan."}],"practiceTitle":"Arrangement Blueprint","practiceInstructions":"Draft a section-by-section texture map and record a short prototype.","challengeTitle":"Pop Song Arrangement Challenge","evidence":"Audio/video of an original or licensed pop-song arrangement with arrangement notes.","rubric":[{"name":"Structural clarity","weight":20},{"name":"Harmony and melody","weight":25},{"name":"Texture and transitions","weight":25},{"name":"Creativity and expression","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["form analysis","texture","register","transitions","personal voice"],"concern":"Copyright/repertoire permissions and use of commercial material require review."},{"level":3,"num":11,"title":"Intro to Jazz Comping","objective":"Comp through a jazz blues or progression using shell voicings and interactive rhythm.","lessons":[{"title":"Role of Jazz Comping","objective":"Explain the pianist''s supporting role."},{"title":"Shell Voicings","objective":"Play selected shell voicings accurately."},{"title":"Interactive Rhythmic Support","objective":"Vary rhythm in response to musical space."}],"practiceTitle":"Shell Voicing Comping Drill","practiceInstructions":"Comp through an approved form using sparse then fuller rhythms.","challengeTitle":"Jazz Comping Challenge","evidence":"Audio/video comping through a blues or teacher-approved form with reflection.","rubric":[{"name":"Voicing accuracy","weight":30},{"name":"Form and harmony","weight":25},{"name":"Rhythmic interaction","weight":20},{"name":"Dynamics and support","weight":15},{"name":"Reflection and completeness","weight":10}],"aria":["shell voicings","form","interaction","space","ensemble listening"],"concern":"Overlap with Module 4 requires distinct introductory shell-voicing scope."},{"level":3,"num":12,"title":"Advanced Capstone: Write & Arrange","objective":"Compose an original melody and deliver a complete advanced piano arrangement.","lessons":[{"title":"Compose a 16-Bar Theme","objective":"Develop a coherent original melody."},{"title":"Arrange Harmony and Form","objective":"Create harmony, texture, and clear form."},{"title":"Polish the Original Performance","objective":"Revise and record a polished performance."}],"practiceTitle":"Advanced Composition Workshop","practiceInstructions":"Draft, receive existing teacher feedback, revise, and rehearse the original work.","challengeTitle":"Write and Arrange Capstone Challenge","evidence":"Polished audio/video of an original arranged piece plus score, chord chart, or structural notes.","rubric":[{"name":"Composition and development","weight":25},{"name":"Harmony and arrangement","weight":25},{"name":"Performance execution","weight":20},{"name":"Form and creativity","weight":20},{"name":"Process and reflection","weight":10}],"aria":["composition process","revision","arrangement","notation alternatives","performance preparation"],"concern":"Source video is unrelated to piano and must not be activated; notation format needs accommodation."},{"level":4,"num":1,"title":"Advanced Harmony and Reharmonization","objective":"Reharmonize a melody using advanced harmonic devices while preserving musical direction.","lessons":[{"title":"Analyze the Original Harmony","objective":"Identify structural harmonic functions."},{"title":"Reharmonization Devices","objective":"Apply substitutions, secondary dominants, or borrowed harmony."},{"title":"Shape a Coherent New Version","objective":"Refine voice leading and melodic support."}],"practiceTitle":"Reharmonization Comparison","practiceInstructions":"Create two reharmonized versions of a short approved melody and compare them.","challengeTitle":"Advanced Reharmonization Challenge","evidence":"Audio/video original and reharmonized versions with harmonic analysis.","rubric":[{"name":"Harmonic accuracy","weight":25},{"name":"Reharmonization effectiveness","weight":30},{"name":"Voice leading","weight":20},{"name":"Musical expression","weight":15},{"name":"Analysis and completeness","weight":10}],"aria":["function","substitutions","melody-harmony fit","restraint","explanation"],"concern":"Acceptable devices and analysis depth require teacher approval."},{"level":4,"num":2,"title":"Counterpoint and Voice Leading","objective":"Create independent melodic voices with controlled motion, balance, and harmonic coherence.","lessons":[{"title":"Voice-Leading Principles","objective":"Apply smooth melodic and harmonic motion."},{"title":"Two-Voice Independence","objective":"Maintain distinct voices rhythmically and melodically."},{"title":"Counterpoint in Composition","objective":"Compose a short contrapuntal passage."}],"practiceTitle":"Two-Voice Study","practiceInstructions":"Write and play a brief two-voice exercise, revising parallels and spacing.","challengeTitle":"Counterpoint and Voice-Leading Challenge","evidence":"Score/chord representation plus audio/video of an original two-voice study.","rubric":[{"name":"Voice independence","weight":30},{"name":"Voice leading","weight":25},{"name":"Harmonic coherence","weight":20},{"name":"Performance clarity","weight":15},{"name":"Process and completeness","weight":10}],"aria":["contrary motion","independence","consonance/dissonance","notation access"],"concern":"Source does not specify species/rule system; criteria are AI-PROPOSED."},{"level":4,"num":3,"title":"Advanced Improvisation Techniques","objective":"Develop long-form improvisation through motif, harmony, rhythm, and narrative shape.","lessons":[{"title":"Motivic Development","objective":"Transform a motif across phrases."},{"title":"Harmonic Navigation","objective":"Target chord tones through changes."},{"title":"Build a Solo Narrative","objective":"Shape tension, release, and pacing."}],"practiceTitle":"Motif Development Lab","practiceInstructions":"Create one motif and develop it through rhythm, register, and harmony.","challengeTitle":"Advanced Improvisation Challenge","evidence":"Audio/video extended improvisation with short analysis of development choices.","rubric":[{"name":"Harmonic navigation","weight":25},{"name":"Motivic development","weight":25},{"name":"Rhythm and phrasing","weight":20},{"name":"Narrative expression","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["motif","chord-tone targeting","pacing","risk-taking","recovery"],"concern":"Length, harmonic form, and accompaniment source require teacher approval."},{"level":4,"num":4,"title":"Gospel and R&B Piano Mastery","objective":"Perform an advanced Gospel/R&B arrangement with stylistic harmony, groove, and expression.","lessons":[{"title":"Genre Language and Context","objective":"Identify stylistic harmonic and rhythmic features respectfully."},{"title":"Advanced Chord Movement","objective":"Use passing chords and advanced movement."},{"title":"Build and Shape the Arrangement","objective":"Create dynamic builds and expressive flow."}],"practiceTitle":"Gospel and R&B Progression Study","practiceInstructions":"Practice approved movements in context and annotate stylistic choices.","challengeTitle":"Gospel and R&B Mastery Challenge","evidence":"Audio/video arrangement or original piece demonstrating harmony, groove, and expressive arc.","rubric":[{"name":"Stylistic harmony","weight":25},{"name":"Groove and timing","weight":25},{"name":"Arrangement and development","weight":20},{"name":"Expression and technique","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["passing chords","call and response","dynamic builds","cultural context"],"concern":"Cultural context, repertoire, and worship-specific material require qualified review."},{"level":4,"num":5,"title":"Artist Study: Stevie Wonder","objective":"Analyze and apply selected Stevie Wonder musical characteristics in an original tribute study.","lessons":[{"title":"Listen and Analyze","objective":"Identify selected compositional and keyboard traits."},{"title":"Harmony, Groove, and Melody","objective":"Practice an approved stylistic device."},{"title":"Create an Original Tribute","objective":"Create original music inspired without copying."}],"practiceTitle":"Stevie Wonder Style Study","practiceInstructions":"Analyze one approved excerpt and transform one characteristic into an original sketch.","challengeTitle":"Stevie Wonder Artist Study Challenge","evidence":"Original audio/video tribute plus analysis citing studied musical features.","rubric":[{"name":"Analysis and understanding","weight":25},{"name":"Stylistic application","weight":25},{"name":"Originality","weight":25},{"name":"Performance and groove","weight":15},{"name":"Reflection and attribution","weight":10}],"aria":["listening analysis","groove","chromatic harmony","attribution","originality"],"concern":"Copyright, source attribution, and avoiding imitation require explicit teacher guidance."},{"level":4,"num":6,"title":"Artist Study: Bill Evans","objective":"Analyze and apply selected Bill Evans voicing, touch, and interaction concepts in an original study.","lessons":[{"title":"Listen for Voicing and Touch","objective":"Identify selected Evans-era musical traits."},{"title":"Lyrical Voice Leading","objective":"Practice close voice leading and lyrical phrasing."},{"title":"Create an Original Jazz Study","objective":"Create original music inspired by the analysis."}],"practiceTitle":"Bill Evans Voicing Study","practiceInstructions":"Analyze an approved passage and write an original voicing progression.","challengeTitle":"Bill Evans Artist Study Challenge","evidence":"Original audio/video jazz study plus analysis and source attribution.","rubric":[{"name":"Analysis and understanding","weight":25},{"name":"Voicing and voice leading","weight":25},{"name":"Originality","weight":20},{"name":"Touch and expression","weight":20},{"name":"Reflection and attribution","weight":10}],"aria":["rootless/close voicing","touch","interaction","historical context","attribution"],"concern":"Repertoire licensing and stylistic/historical framing require qualified teacher review."},{"level":4,"num":7,"title":"Accompaniment and Ensemble Playing","objective":"Support another performer through listening, adaptive voicing, rhythm, and dynamic balance.","lessons":[{"title":"Accompaniment Roles","objective":"Choose textures that support a lead part."},{"title":"Follow and Respond","objective":"Adjust timing and dynamics through listening."},{"title":"Rehearse with an Ensemble Plan","objective":"Plan cues, form, and recovery strategies."}],"practiceTitle":"Accompaniment Response Practice","practiceInstructions":"Accompany a recording, collaborator, or teacher-led simulation while varying density.","challengeTitle":"Ensemble Accompaniment Challenge","evidence":"Recorded/live accompaniment with collaborator or approved simulated lead, plus reflection.","rubric":[{"name":"Supportive harmony","weight":25},{"name":"Timing and responsiveness","weight":25},{"name":"Dynamic balance","weight":20},{"name":"Form and communication","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["listening","balance","cues","adaptability","supportive role"],"concern":"Collaborator access requires approved backing-track or teacher-observed alternative."},{"level":4,"num":8,"title":"Playing in a Band","objective":"Perform a pianist''s band role with rhythmic lock, communication, and adaptable texture.","lessons":[{"title":"Rhythm-Section Lock","objective":"Coordinate with bass and drums."},{"title":"Cues and Musical Communication","objective":"Use visual and musical cues appropriately."},{"title":"Shape a Band Arrangement","objective":"Adjust register and density across sections."}],"practiceTitle":"Band-Rehearsal Simulation","practiceInstructions":"Practice with an approved ensemble, track, or simulated rhythm section and mark cues.","challengeTitle":"Band Performance Challenge","evidence":"Live/recorded ensemble or approved simulation demonstrating lock, cues, and role awareness.","rubric":[{"name":"Time and groove","weight":25},{"name":"Listening and interaction","weight":25},{"name":"Part accuracy","weight":20},{"name":"Communication and adaptability","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["pocket","cues","register","arrangement role","recovery"],"concern":"Actual ensemble access and backing materials require equitable alternatives."},{"level":4,"num":9,"title":"Rock & R&B Organ Techniques","objective":"Apply organ-specific sound controls, comping patterns, and gestures safely on an available keyboard.","lessons":[{"title":"Organ Sound and Controls","objective":"Explain drawbar/rotary concepts using available controls."},{"title":"Comping and Riffs","objective":"Play selected organ comping patterns."},{"title":"Safe Organ Articulation","objective":"Use approved gestures without unsafe force."}],"practiceTitle":"Organ Texture Practice","practiceInstructions":"Explore two organ registrations and practice an approved riff/comping pattern.","challengeTitle":"Rock and R&B Organ Challenge","evidence":"Audio/video organ-style performance on available equipment with sound-choice explanation.","rubric":[{"name":"Organ sound control","weight":20},{"name":"Pattern and note accuracy","weight":25},{"name":"Groove and timing","weight":25},{"name":"Technique and style","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["registration","rotary effect","comping","palm smear safety","glissando safety"],"concern":"Hardware varies; palm smears/glissandos must be optional and safety-reviewed."},{"level":4,"num":10,"title":"Professional Performance Skills","objective":"Prepare and deliver a professional-quality performance with reliable technique, communication, and recovery.","lessons":[{"title":"Professional Preparation","objective":"Create a technical and logistical performance plan."},{"title":"Stage Communication","objective":"Communicate musical intent to an audience."},{"title":"Performance Recovery and Review","objective":"Recover from errors and evaluate the result."}],"practiceTitle":"Professional Run-Through","practiceInstructions":"Complete a timed setup, sound check simulation, performance, and review.","challengeTitle":"Professional Performance Challenge","evidence":"Polished live/recorded performance plus preparation checklist and self-evaluation.","rubric":[{"name":"Technical reliability","weight":25},{"name":"Musical communication","weight":25},{"name":"Stage readiness","weight":20},{"name":"Recovery and professionalism","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["preparation","stage presence","recovery","sound check","audience communication"],"concern":"Venue, equipment, and accessibility expectations require individualized planning."},{"level":4,"num":11,"title":"The Working Musician","objective":"Create a practical pianist career plan covering opportunities, professionalism, promotion, and basic finances.","lessons":[{"title":"Pianist Career Options","objective":"Compare relevant performance and creative roles."},{"title":"Professional Communication and Networking","objective":"Prepare professional outreach and conduct standards."},{"title":"Build a Working-Musician Plan","objective":"Draft goals, materials, and a basic budget."}],"practiceTitle":"Musician Career Planning Practice","practiceInstructions":"Draft a one-page opportunity map, outreach message, and next-step checklist.","challengeTitle":"Working Musician Portfolio Challenge","evidence":"Career plan plus approved professional artifact and teacher/staff review evidence.","rubric":[{"name":"Career understanding","weight":20},{"name":"Professional plan","weight":25},{"name":"Communication artifact","weight":20},{"name":"Practical readiness","weight":25},{"name":"Reflection and completeness","weight":10}],"aria":["career pathways","networking","budgeting","marketing","boundaries"],"concern":"Financial/legal guidance must remain educational; local opportunity claims require review."},{"level":4,"num":12,"title":"Final Capstone: The Master Recital","objective":"Plan, arrange, and perform a 15-minute recital of contrasting works demonstrating artistic identity and mastery.","lessons":[{"title":"Design the Recital Program","objective":"Select contrasting repertoire and justify the program."},{"title":"Rehearse, Arrange, and Produce","objective":"Prepare arrangements, transitions, and production details."},{"title":"Perform and Evaluate the Master Recital","objective":"Deliver and critically evaluate the complete recital."}],"practiceTitle":"Master Recital Production Rehearsal","practiceInstructions":"Run the full program with transitions, timing, recording setup, and contingency plan.","challengeTitle":"Master Recital Capstone Challenge","evidence":"Professional-quality live/recorded approximately 15-minute recital with three contrasting pieces, at least one original arrangement, program notes, and reflection.","rubric":[{"name":"Program design and preparation","weight":20},{"name":"Technical and musical mastery","weight":25},{"name":"Contrast and artistic identity","weight":20},{"name":"Performance professionalism","weight":25},{"name":"Reflection and documentation","weight":10}],"aria":["program design","endurance","transitions","artistic identity","production planning"],"concern":"Repertoire rights, duration accommodations, venue/equipment, and alternative evidence require leadership and teacher approval."}]'::jsonb) as x(level int,num int,title text,objective text,lessons jsonb,"practiceTitle" text,"practiceInstructions" text,"challengeTitle" text,evidence text,rubric jsonb,aria jsonb,concern text)), piano as(select id from public.courses where slug='piano'), level_report as(
 select n.level_number,case when l.id is null then 'CREATE_MISSING' when n.level_number=1 and l.status='draft' and l.title='Beginner' and l.description='Beginner Piano foundations. Draft review only.' and l.learning_objectives=array['Build healthy setup and foundational keyboard control.']::text[] and l.core_xp_target=6250 and l.review_notes='Piano Module 1 pilot; AI-PROPOSED content requires leadership and piano-teacher review.' and l.approved_by is null and l.approved_at is null then 'REUSE_EXACT' when n.level_number>1 and l.status='draft' and l.title=(array['Beginner','Intermediate','Advanced','Master'])[n.level_number] and l.description=(array['Beginner','Intermediate','Advanced','Master'])[n.level_number]||' Piano curriculum. Draft review only.' and l.learning_objectives=array['Complete the source-aligned Piano level curriculum.']::text[] and l.core_xp_target=6250 and l.review_notes='Piano full draft rollout 202608130001; metadata target reconciliation deferred.' and l.approved_by is null and l.approved_at is null then 'REUSE_EXACT' else 'BLOCK_CONFLICT' end action
 from generate_series(1,4) n(level_number) left join public.course_levels l on l.course_id=(select id from piano) and l.level_number=n.level_number
), module_report as(
 select m.level,m.num,m.title,case when cm.id is null then 'CREATE_MISSING' when cm.status='draft' and cm.title=m.title and cm.description=m.objective and cm.short_intro=m.objective and cm.sort_order=(m.level-1)*12+m.num and cm.core_xp=625 and cm.intro_core_xp=50 and cm.video_core_xp=100 and cm.assignment_core_xp=350 and cm.mastery_core_xp=125 and cm.core_unlock_threshold=438 and cm.lab_tool_id is null and cm.active_instructional_media_id is null and cm.primary_video_url is null and cm.approved_by is null and cm.approved_at is null then 'REUSE_EXACT' else 'BLOCK_CONFLICT' end action
 from manifest m left join public.course_levels l on l.course_id=(select id from piano) and l.level_number=m.level left join public.course_modules cm on cm.course_level_id=l.id and cm.level_module_number=m.num
), findings as(
 select 'PIANO_IDENTITY' code,case when (select count(*) from public.courses where slug='piano')=1 then 'PASS' else 'FAIL' end result
 union all select 'SAFE_DRAFT_ISOLATION',case when (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('jpac_sync_enrollment_progress','jpac_enforce_canonical_enrollment_progress') and pg_get_functiondef(p.oid) like '%m.status = ''published''%')=2 then 'PASS' else 'FAIL' end
 union all select 'MODULE1_REUSE',case when (select count(*) from public.course_modules m join public.courses c on c.id=m.course_id join public.course_levels l on l.id=m.course_level_id where c.slug='piano' and l.level_number=1 and m.level_module_number=1 and m.title='Piano Posture and Hand Position' and m.status='draft' and m.core_xp=625 and m.core_unlock_threshold=438)=1 then 'PASS' else 'FAIL' end
 union all select 'LEVEL_COMPATIBILITY',case when exists(select 1 from level_report where action='BLOCK_CONFLICT') then 'FAIL' else 'PASS' end
 union all select 'MODULE_COMPATIBILITY',case when exists(select 1 from module_report where action='BLOCK_CONFLICT') then 'FAIL' else 'PASS' end
 union all select 'CHILD_COMPATIBILITY',case when exists(select 1 from manifest mf join public.course_levels cl on cl.course_id=(select id from piano) and cl.level_number=mf.level join public.course_modules m on m.course_level_id=cl.id and m.level_module_number=mf.num where (exists(select 1 from public.lessons where module_id=m.id) or exists(select 1 from public.activities where module_id=m.id)) and ((select count(*) from public.lessons where module_id=m.id)<>3 or (select count(*) from public.activities where module_id=m.id)<>2 or exists(select 1 from jsonb_array_elements(mf.lessons) with ordinality expected(item,ord) left join public.lessons l on l.module_id=m.id and l.sort_order=ord where l.id is null or l.title is distinct from expected.item->>'title' or l.learning_objective is distinct from expected.item->>'objective' or l.status<>'draft') or not exists(select 1 from public.activities a where a.module_id=m.id and a.title=mf."practiceTitle" and a.activity_type='practice' and a.xp_type='bonus' and a.xp_reward=0 and not a.required and a.status='draft') or not exists(select 1 from public.activities a where a.module_id=m.id and a.title=mf."challengeTitle" and a.activity_type='performance' and a.xp_type='core' and a.xp_reward=350 and a.required and a.status='draft' and a.passing_score=70 and a.allows_resubmission))) then 'FAIL' else 'PASS' end
 union all select 'EVIDENCE_CONFLICT',case when exists(select 1 from public.course_modules m join public.courses c on c.id=m.course_id join public.course_levels cl on cl.id=m.course_level_id where c.slug='piano' and not(cl.level_number=1 and m.level_module_number=1) and (exists(select 1 from public.lessons l join public.lesson_progress p on p.lesson_id=l.id where l.module_id=m.id) or exists(select 1 from public.activities a join public.submissions s on s.activity_id=a.id where a.module_id=m.id) or exists(select 1 from public.activities a join public.activity_progress p on p.activity_id=a.id where a.module_id=m.id) or exists(select 1 from public.activities a join public.practice_logs p on p.activity_id=a.id where a.module_id=m.id) or exists(select 1 from public.activities a join public.portfolio_projects p on p.activity_id=a.id where a.module_id=m.id) or exists(select 1 from public.xp_ledger x where x.module_id=m.id) or exists(select 1 from public.module_instructional_media im where im.module_id=m.id))) then 'FAIL' else 'PASS' end
)
select 'LEVEL_REPORT' section,level_number::text item,action result from level_report
union all select 'MODULE_REPORT',level||'.'||num||' '||title,action from module_report
union all select 'FINDING',code,result from findings
union all select 'PRESERVATION_BASELINE','SINGING_CURRICULUM',md5(coalesce((select string_agg(to_jsonb(m)::text,'|' order by m.id) from public.course_modules m join public.courses c on c.id=m.course_id where c.slug='singing'),'')||coalesce((select string_agg(to_jsonb(l)::text,'|' order by l.id) from public.lessons l join public.course_modules m on m.id=l.module_id join public.courses c on c.id=m.course_id where c.slug='singing'),'')||coalesce((select string_agg(to_jsonb(a)::text,'|' order by a.id) from public.activities a join public.courses c on c.id=a.course_id where c.slug='singing'),''))
union all select 'PRESERVATION_BASELINE','STUDENT_STATE',md5(coalesce((select string_agg(to_jsonb(e)::text,'|' order by e.id) from public.enrollments e),'')||coalesce((select string_agg(to_jsonb(s)::text,'|' order by s.id) from public.submissions s),'')||coalesce((select string_agg(to_jsonb(x)::text,'|' order by x.id) from public.xp_ledger x),''))
union all select 'PRESERVATION_BASELINE','SHARED_FUNCTIONS',md5(coalesce((select string_agg(pg_get_functiondef(p.oid),'|' order by p.proname,p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'jpac_%'),''))
union all select 'PRESERVATION_BASELINE','CAREER_PATHS',md5(coalesce((select string_agg(to_jsonb(cp)::text,'|' order by cp.id) from public.career_paths cp),'')||coalesce((select string_agg(to_jsonb(cm)::text,'|' order by cm.id) from public.career_milestones cm),''))
union all select 'PRESERVATION_BASELINE','PIANO_MODULE_1',md5(coalesce((select string_agg(to_jsonb(m)::text,'|' order by m.id) from public.course_modules m join public.course_levels l on l.id=m.course_level_id where m.course_id=(select id from piano) and l.level_number=1 and m.level_module_number=1),'')||coalesce((select string_agg(to_jsonb(ls)::text,'|' order by ls.id) from public.lessons ls join public.course_modules m on m.id=ls.module_id join public.course_levels l on l.id=m.course_level_id where m.course_id=(select id from piano) and l.level_number=1 and m.level_module_number=1),'')||coalesce((select string_agg(to_jsonb(a)::text,'|' order by a.id) from public.activities a join public.course_modules m on m.id=a.module_id join public.course_levels l on l.id=m.course_level_id where m.course_id=(select id from piano) and l.level_number=1 and m.level_module_number=1),''))
union all select 'READINESS','PIANO_FULL_DRAFT_ROLLOUT',case when exists(select 1 from findings where result='FAIL') then 'FAIL' else 'PASS: READY FOR MIGRATION' end;
rollback;
